class Solution:
    def unhappyFriends(self, n: int, preferences: List[List[int]], pairs: List[List[int]]) -> int:
        partner = {}
        for x, y in pairs:
            partner[x] = y
            partner[y] = x
        ans = 0
        for x in range(n):
            y = partner[x]
            found = False
            for u in range(n):
                if u == x or u == y:
                    continue
                if preferences[x].index(u) < preferences[x].index(y) and preferences[u].index(x) < preferences[u].index(partner[u]):
                    found = True
                    break
            ans += found
        return ans

