class Solution {
public:
    int unhappyFriends(int n, vector<vector<int>>& preferences, vector<vector<int>>& pairs) {
        vector<int> partner(n, -1);
        for (auto& p : pairs) { partner[p[0]] = p[1]; partner[p[1]] = p[0]; }
        auto posOf = [](const vector<int>& pref, int who) {
            return find(pref.begin(), pref.end(), who) - pref.begin();
        };
        int ans = 0;
        for (int x = 0; x < n; x++) {
            int y = partner[x];
            bool bad = false;
            for (int u = 0; u < n && !bad; u++) {
                if (u == x || u == y) continue;
                if (posOf(preferences[x], u) < posOf(preferences[x], y)
                        && posOf(preferences[u], x) < posOf(preferences[u], partner[u]))
                    bad = true;
            }
            ans += bad;
        }
        return ans;
    }
};

