class Solution {
    public int unhappyFriends(int n, int[][] preferences, int[][] pairs) {
        int[] partner = new int[n];
        for (int[] p : pairs) { partner[p[0]] = p[1]; partner[p[1]] = p[0]; }
        int ans = 0;
        for (int x = 0; x < n; x++) {
            int y = partner[x];
            boolean bad = false;
            for (int u = 0; u < n && !bad; u++) {
                if (u == x || u == y) continue;
                if (idx(preferences[x], u) < idx(preferences[x], y)
                        && idx(preferences[u], x) < idx(preferences[u], partner[u]))
                    bad = true;
            }
            if (bad) ans++;
        }
        return ans;
    }

    private int idx(int[] pref, int who) {
        for (int i = 0; i < pref.length; i++) if (pref[i] == who) return i;
        return -1;
    }
}

